const COLL = { fallbackFamily: null, families: {}, weights: {} };
const FAMILIES = ["Vazirmatn", "Inter", "Roboto", "Segoe UI", "Arial", "Helvetica Neue", "sans-serif"];
const WEIGHTS = { 300: "Light", 400: "Regular", 500: "Medium", 600: "SemiBold", 700: "Bold", 800: "ExtraBold" };

const FAMILY = DATA.typography.familyPrimary.split(",")[0].replace(/['"]/g, "").trim();
const CODE_FAMILY = DATA.typography.familyCode.split(",")[0].replace(/['"]/g, "").trim();

function hexToRgb(h) {
  h = h.replace("#", "");
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  return { r: parseInt(h.slice(0, 2), 16) / 255, g: parseInt(h.slice(2, 4), 16) / 255, b: parseInt(h.slice(4, 6), 16) / 255 };
}

function rgbToCss(h) { const c = hexToRgb(h); return `rgb(${Math.round(c.r * 255)}, ${Math.round(c.g * 255)}, ${Math.round(c.b * 255)})`; }

let COLLECTION = null;

function buildPage() {
  const pageName = "tamasmarket Design System";
  let page = figma.root.children.find((p) => p.name === pageName);
  if (!page) page = figma.createPage();
  page.name = pageName;
  figma.currentPage = page;
  for (const n of [...page.children]) n.remove();
  return page;
}

function section(parent, title, x, y, w) {
  const titleNode = figma.createText();
  titleNode.fontName = { family: COLL.family, style: COLL.weightsStrong };
  titleNode.fontSize = 18;
  titleNode.characters = title;
  titleNode.x = x; titleNode.y = y;
  parent.appendChild(titleNode);
  const line = figma.createRectangle();
  line.resize(w, 1);
  line.fills = [{ type: "SOLID", color: hexToRgb("#e0e0e0") }];
  line.x = x; line.y = y + 22;
  parent.appendChild(line);
  return { titleNode, line };
}

function chip(parent, label, hex, x, y, size, radius) {
  const rect = figma.createRectangle();
  rect.resize(size, size);
  rect.fills = [{ type: "SOLID", color: hexToRgb(hex), opacity: 1 }];
  rect.cornerRadius = radius || 6;
  rect.x = x; rect.y = y;
  rect.name = label;
  parent.appendChild(rect);
  if (COLL.hexToStyle[hex]) rect.fillStyleId = COLL.hexToStyle[hex];
  return rect;
}

function text(parent, str, x, y, size, weight, colorHex, width) {
  const n = figma.createText();
  n.characters = str;
  n.fontName = { family: COLL.family, style: weight };
  n.fontSize = size;
  n.fills = [{ type: "SOLID", color: hexToRgb(colorHex || "#1d1d1f") }];
  n.x = x; n.y = y;
  if (width) n.resize(width, n.height);
  parent.appendChild(n);
  return n;
}

function buildMain() {
  const page = buildPage();
  const w = 900;

  // Headers
  let y = 24;
  const titleBig = text(page, "tamasmarket", 24, y, 48, COLL.weightsStrong, "#08798f", 600);
  const sub = text(page, "تماس مارکت | فروشگاه دیجیتال", 24, y + 56, 18, COLL.weightsRegular, "#1d1d1f", 600);
  const meta = text(page, `Design system · ${Object.keys(DATA.tokens).length} tokens × ${Object.keys(DATA.themeModes).length} themes · Vazirmatn FD`, 24, y + 86, 12, COLL.weightsRegular, "#7a7a7a", 600);
  y += 130;

  // Section: Colors (active theme)
  section(page, "Colors — active theme", 24, y, w - 48);
  y += 48;
  const colorMap = Object.entries(DATA.activeTokens).filter(([k]) => /^color/.test(k));
  const width = 128, height = 56;
  const perRow = Math.floor((w - 48) / (width + 16));
  let ci = 0;
  for (const [name, val] of colorMap) {
    if (typeof val !== "string" || !val.startsWith("#")) continue;
    const col = ci % perRow, row = Math.floor(ci / perRow);
    const x = 24 + col * (width + 16);
    const yy = y + row * (height + 52);
    const r = chip(page, name, val, x, yy, width, height, 8);
    const lab = text(page, name, x, yy + height + 6, 9, COLL.weightsRegular, "#7a7a7a", width);
    const hexT = text(page, val.toUpperCase(), x, yy + height + 18, 9, COLL.weightsRegular, "#7a7a7a", width);
    ci++;
  }
  y += Math.ceil(ci / perRow) * (height + 52) + 30;

  // Section: Primary ramp
  section(page, "Primary palette ramp", 24, y, w - 48);
  y += 48;
  (DATA.primaryPalette || []).forEach((hex, i) => {
    const r = chip(page, "ramp-" + i, hex, 24 + i * (40 + 8), y, 40, 12, 6);
  });
  y += 70;

  // Section: Typography
  section(page, "Typography (Vazirmatn FD)", 24, y, w - 48);
  y += 48;
  const typeItems = [
    ["Display", DATA.typography.fontSizeXL, 800, "#1d1d1f"],
    ["Heading 1", DATA.typography.fontSizeHeading1, 700, "#1d1d1f"],
    ["Heading 2", DATA.typography.fontSizeHeading2, 700, "#1d1d1f"],
    ["Heading 3", DATA.typography.fontSizeHeading3, 600, "#1d1d1f"],
    ["Heading 4", DATA.typography.fontSizeHeading4, 600, "#1d1d1f"],
    ["Heading 5", DATA.typography.fontSizeHeading5, 600, "#1d1d1f"],
    ["Body", DATA.typography.fontSize, 400, "#1d1d1f"],
    ["Small", DATA.typography.fontSizeSM, 400, "#7a7a7a"],
  ];
  let ty = y;
  typeItems.forEach(([label, size, wgt, colr]) => {
    const sample = "اقلام دیجیتال · Große Auswahl · ۱۲۳۴";
    text(page, label, 24, ty, 11, COLL.weightsMedium, "#7a7a7a", 130);
    text(page, sample, 160, ty, size, COLL.weights[String(wgt)] || "Regular", colr, w - 220);
    ty += size + 26;
  });
  y = ty + 20;

  // Section: Icons
  section(page, "Category icons", 24, y, w - 48);
  y += 48;
  const icons = Object.entries(DATA.icons);
  const iconSize = 56, iconCols = 6;
  icons.forEach(([name, svg], i) => {
    const col = i % iconCols, row = Math.floor(i / iconCols);
    const x = 24 + col * (iconSize + 24);
    const yy = y + row * (iconSize + 30);
    const node = figma.createNodeFromSvgAsync(svg);
    Promise.resolve(node).then((n) => {
      n.resize(iconSize, iconSize);
      n.x = x; n.y = yy;
      page.appendChild(n);
    });
    const lab = text(page, name.replace(/-/g, " "), x, yy + iconSize + 4, 9, COLL.weightsRegular, "#7a7a7a", iconSize);
  });
  y += Math.ceil(icons.length / iconCols) * (iconSize + 30) + 30;

  // Section: Spacing & Radius
  section(page, "Spacing & radius tokens", 24, y, w - 48);
  y += 48;
  const sizeTokens = Object.entries(DATA.activeTokens).filter(([k]) => /^size|^borderRadius|^lineWidth|^controlHeight/.test(k));
  let si = 0;
  for (const [name, val] of sizeTokens) {
    if (typeof val === "string" && val.startsWith("#")) continue;
    const num = parseInt(val, 10) || 0;
    const x = 24 + si * 20;
    const r = figma.createRectangle();
    r.resize(num, 16);
    r.fills = [{ type: "SOLID", color: hexToRgb("#08798f") }];
    r.x = x; r.y = y;
    page.appendChild(r);
    const lab = text(page, `${name} ${num}`, x, y + 22, 9, COLL.weightsRegular, "#7a7a7a", 100);
    si++;
  }
  y += 60;
}

function buildThemes() {
  // Create variable collection + styles keyed per theme
  const collection = figma.variables.createVariableCollection("tamasmarket");
  collection.renameMode(collection.modes[0].modeId, "default");
  Object.keys(DATA.themeModes).forEach((m) => {
    if (m !== "default") {
      try { collection.addMode(m); } catch (e) {}
    }
  });

  const modeIds = {};
  collection.modes.forEach((m) => (modeIds[m.name] = m.modeId));

  Object.entries(DATA.themeTokens).forEach(([themeName, tokens]) => {
    const modeId = modeIds[themeName];
    Object.entries(tokens).forEach(([name, val]) => {
      if (typeof val !== "string" || !val.startsWith("#")) return;
      let v = COLLECTION ? COLLECTION.find((c) => c.name === name) : null;
      if (!v) {
        v = figma.variables.createVariable(name, collection, "COLOR");
        COLLECTION = COLLECTION || [];
        v.scopes = ["ALL_FILLS"];
        COLLECTION.push(v);
      }
      const rgb = hexToRgb(val);
      v.setValueForMode(modeId, { r: rgb.r, g: rgb.g, b: rgb.b, a: 1 });
    });
  });

  // Export paint styles for active theme colors too
  Object.entries(DATA.activeTokens).forEach(([name, val]) => {
    if (typeof val !== "string" || !val.startsWith("#")) return;
    const style = figma.createPaintStyle();
    style.name = "colors/" + name;
    style.paints = [{ type: "SOLID", color: hexToRgb(val), opacity: 1 }];
    if (!COLL.hexToStyle) COLL.hexToStyle = {};
    COLL.hexToStyle[val.toLowerCase()] = style.id;
  });
}

async function run() {
  // Load fonts
  COLL.fallbackFamily = null;
  COLL.fallbacks = FAMILIES.filter((f) => f !== FAMILY).concat(["Inter", "Arial"]);
  COLL.family = FAMILY; COLL.weightsRegular = "Regular"; COLL.weightsStrong = "Bold"; COLL.weightsMedium = "Medium";
  try {
    await figma.loadFontAsync({ family: FAMILY, style: "Regular" });
  } catch (e) {
    COLL.family = "Inter";
  }
  try { await figma.loadFontAsync({ family: COLL.family, style: "Regular" }); } catch (e) {}
  try { await figma.loadFontAsync({ family: COLL.family, style: "Medium" }); } catch (e) {}
  try { await figma.loadFontAsync({ family: COLL.family, style: "SemiBold" }); } catch (e) {}
  try { await figma.loadFontAsync({ family: COLL.family, style: "Bold" }); } catch (e) {}
  try { await figma.loadFontAsync({ family: COLL.family, style: "ExtraBold" }); } catch (e) {}

  await figma.loadFontAsync({ family: "Inter", style: "Regular" });

  COLL.weights = {
    "300": "Light", "400": "Regular", "500": "Medium", "600": "SemiBold", "700": "Bold", "800": "ExtraBold"
  };

  buildThemes();
  buildMain();
  figma.viewport.scrollAndZoomIntoView(figma.currentPage.children[0]);
  figma.notify("tamasmarket design system built ✓");
  figma.closePlugin();
}

run().catch((err) => {
  console.error(err);
  figma.closePlugin("Build error: " + err.message);
});